const root = $json || {};
const whatsapp = root.whatsapp && typeof root.whatsapp === 'object' ? root.whatsapp : {};
const text = String(root.outbound_text || whatsapp.text || root.message || root.reply_text || root.clarifying_question || "Ainda não consigo ler esse tipo de mensagem por aqui. Me manda em texto? Se for fatura, pode enviar o PDF.").trim();
