const normalized = $('Normalize Evolution Payload').first().json || {};
const root = normalized.raw || $json || {};
const user = normalized.user || root.user || {};
const conversation = normalized.conversation || root.conversation || {};
const authorized = user.authorized !== false && Number(user.id || 0) > 0;
return [{ json: { ...root, authorized, code: authorized ? 'AUTHORIZED_BY_ORCHESTRATOR' : 'NOT_AUTHORIZED', user, conversation, phone: normalized.phone, whatsapp: { ...(root.whatsapp || {}), phone: normalized.phone, message_text: normalized.message_text, message_id: normalized.message_id, instance: normalized.instance } } }];

