const whatsapp = root.whatsapp && typeof root.whatsapp === 'object' ? root.whatsapp : {};
const text = String(root.outbound_text || whatsapp.text || root.message || root.reply_text || root.clarifying_question || "Esse número ainda não está liberado no AcerttaPay. Ative o WhatsApp nas Configurações do app.").trim();
return [{ json: { ...root, ok: root.ok !== false, workflow_key: root.workflow_key || "5.1", outbound_text: text, send_by_orchestrator: true, whatsapp: { ...whatsapp, text } } }];

function cleanJsonContent(value) {
  if (value && typeof value === 'object') return value;
  const raw = String(value || '').trim();
  if (!raw) return '';
  const withoutFence = raw.replace(/^```(?:json)?\s*/i, '').replace(/```$/i, '').trim();
  const first = withoutFence.indexOf('{');
  const last = withoutFence.lastIndexOf('}');
  if (first >= 0 && last > first) return withoutFence.slice(first, last + 1);
  return withoutFence;
}
const content = $json.output ?? $json.text ?? $json.response ?? $json.choices?.[0]?.message?.content ?? '';
let parsed;
try {
  const cleaned = cleanJsonContent(content);
  parsed = typeof cleaned === 'object' ? cleaned : JSON.parse(cleaned);
} catch (error) {
  parsed = {
    intent: 'help',
    confidence: 0,
    needs_clarification: false,
    reply_text: 'Posso te ajudar com finanças mensais fora do cartão: lançar conta, listar entradas/saídas, marcar como paga, corrigir ou apagar. Ex.: lançar aluguel de R$ 2.500 para junho. 😉'
  };
}
if (!parsed || typeof parsed !== 'object') parsed = { intent: 'help', reply_text: 'Me manda o que você quer fazer nas finanças mensais fora do cartão.' };
const apiIntents = new Set(['create_monthly_finance','list_monthly_finances','mark_finance_paid','mark_finance_unpaid','update_monthly_finance','delete_monthly_finance']);
parsed.should_call_api = apiIntents.has(String(parsed.intent || '')) && parsed.needs_clarification !== true;
if (parsed.needs_clarification === true && !parsed.clarifying_question) parsed.clarifying_question = 'Me dá mais um detalhe para eu não lançar essa conta no mês errado?';
if (['greeting','help'].includes(String(parsed.intent || '')) && !parsed.reply_text) {
  parsed.reply_text = 'Oi! Aqui é seu concierge das finanças mensais do AcerttaPay. Posso lançar contas fora do cartão, listar o mês, marcar como paga, corrigir ou apagar. Ex.: *lançar aluguel de R$ 2.500 para junho*. 📒';
}
if (String(parsed.intent || '') === 'out_of_scope' && !parsed.reply_text) parsed.reply_text = 'Essa parece compra de cartão. Para isso, usa o fluxo de Compra Assistida. Aqui eu cuido das contas e entradas fora do cartão. 😉';
return [{ json: parsed }];

const root = $json || {};
const whatsapp = root.whatsapp && typeof root.whatsapp === 'object' ? root.whatsapp : {};
const text = String(root.outbound_text || whatsapp.text || root.message || root.reply_text || root.clarifying_question || "Pedido processado no AcerttaPay.").trim();
return [{ json: { ...root, ok: root.ok !== false, workflow_key: root.workflow_key || "5.1", outbound_text: text, send_by_orchestrator: true, whatsapp: { ...whatsapp, text } } }];

const parsed = $json || {};
const intent = String(parsed.intent || '').trim();
const phone = $('Normalize Evolution Payload').first().json.phone;
const source = {
  channel: 'whatsapp',
  instance: $('Normalize Evolution Payload').first().json.instance,
  message_id: $('Normalize Evolution Payload').first().json.message_id,
  raw_text: $('Normalize Evolution Payload').first().json.message_text
};
const query = parsed.query || {};
const finance = parsed.finance || {};
const target = parsed.target || {};
const patch = parsed.patch || {};
let endpoint = '/api/automation/v1/monthly-finances/search';
let body = { phone, source, query };
let idempotencySuffix = intent;
function cleanId(value) {
  return String(value || '0').replace(/[^0-9]/g, '') || '0';
}
function targetId() {
  return cleanId(target.finance_id || target.id || parsed.finance_id || parsed.id);
}
if (intent === 'list_monthly_finances') {
  endpoint = '/api/automation/v1/monthly-finances/search';
} else if (intent === 'create_monthly_finance') {
  endpoint = '/api/automation/v1/monthly-finances';
  body.finance = finance;
  idempotencySuffix += ':' + (finance.description || 'nova');
} else if (intent === 'mark_finance_paid') {
  const id = targetId();
  endpoint = `/api/automation/v1/monthly-finances/${id}/mark-paid`;
  body.query = { ...query, finance_hint: target.finance_hint || query.finance_hint || finance.description || null };
  idempotencySuffix += ':' + id + ':' + (target.finance_hint || query.finance_hint || 'hint');
} else if (intent === 'mark_finance_unpaid') {
  const id = targetId();
